"use strict";
let event = null;
let doc = null;
exports.nextEvent = () =>
  (event = {
    type: "delta",
    usage: { input_tokens: 1, cache_creation: { ephemeral_1h_input_tokens: 7 } },
  });
exports.touchEvent = () => {
  event.usage.cache_creation.ephemeral_1h_input_tokens = 99;
};
exports.load = () =>
  (doc ??= { name: "dark", colors: { accent: "#fff", muted: 8 }, vars: { base: "#000" } });
exports.bump = () => {
  doc.colors.accent = "#eee";
  doc.vars.base = "#111";
};
exports.same = (v) => v === doc.colors;
